// Normalize a search string for fuzzy matching (strips spaces, hyphens, station suffixes)
export function normalizeSearchString(str: string): string {
  if (!str) return '';
  return str
    .toLowerCase()
    .trim()
    .replace(/[\s\-_/・,.]+/g, '')
    .replace(/station$/i, '')
    .replace(/sta$/i, '')
    .replace(/eki$/i, '')
    .replace(/駅$/i, '');
}

// Helper: Find all matching stations for a user search query with relevance scoring
export function findStationsByQuery(searchQuery: string): StationRecord[] {
  if (!searchQuery) return [];
  const rawLower = searchQuery.trim().toLowerCase();
  const normalizedQuery = normalizeSearchString(searchQuery);

  if (!rawLower && !normalizedQuery) return [];

  const scored: { station: StationRecord; score: number }[] = [];

  for (const st of JAPAN_STATIONS) {
    let score = 0;
    const normStationId = normalizeSearchString(st.station_id);
    const normStationName = normalizeSearchString(st.station_name);
    const normParentName = normalizeSearchString(st.parent_location_name);
    const stNameLower = st.station_name.toLowerCase();

    // 1. Exact matches
    if (st.station_id.toLowerCase() === rawLower || stNameLower === rawLower || st.japanese_name === searchQuery.trim()) {
      score = 100;
    } else if (normStationId === normalizedQuery || normStationName === normalizedQuery) {
      score = 95;
    } else if (st.aliases.some(a => a.toLowerCase() === rawLower || a === searchQuery.trim() || normalizeSearchString(a) === normalizedQuery)) {
      score = 90;
    } else if (stNameLower.startsWith(rawLower) || normStationName.startsWith(normalizedQuery)) {
      score = 80;
    } else if (st.station_name.toLowerCase().includes(rawLower) || st.japanese_name.includes(searchQuery.trim())) {
      score = 70;
    } else if (normStationId.includes(normalizedQuery) || normStationName.includes(normalizedQuery)) {
      score = 65;
    } else if (st.aliases.some(a => a.toLowerCase().includes(rawLower) || a.includes(searchQuery.trim()) || normalizeSearchString(a).includes(normalizedQuery))) {
      score = 55;
    } else if (st.parent_location_name.toLowerCase().includes(rawLower) || normParentName.includes(normalizedQuery) || st.city.toLowerCase().includes(rawLower)) {
      score = 40;
    } else if (st.lines.some(l => l.toLowerCase().includes(rawLower))) {
      score = 25;
    } else if (st.food_focus.toLowerCase().includes(rawLower)) {
      score = 15;
    }

    if (score > 0) {
      scored.push({ station: st, score });
    }
  }

  // Sort by highest score first
  scored.sort((a, b) => b.score - a.score);

  return scored.map(s => s.station);
}

// Convert a StationRecord to a LocationWithCoords
export function stationToLocation(station: StationRecord): LocationWithCoords {
  return {
    location_id: station.station_id,
    location_name: station.station_name,
    type: 'Station' as any,
    parent_location_id: station.parent_location_id,
    city: station.city,
    prefecture_id: station.prefecture_id,
    region_id: station.region_id,
    coverage_phase: 1,
    food_focus: station.food_focus,
    admin_note: `${station.station_name} transit hub (${station.lines.slice(0, 2).join(', ')}) connected to ${station.parent_location_name}`,
    content_status: 'Published',
    image_url: null,
    lat: station.lat,
    lng: station.lng,
  };
}

// Find a station by ID
export function getStationById(stationId: string): StationRecord | undefined {
  if (!stationId) return undefined;
  const targetId = stationId.toLowerCase().trim();
  const normalizedTarget = normalizeSearchString(stationId);

  return JAPAN_STATIONS.find(st =>
    st.station_id.toLowerCase() === targetId ||
    normalizeSearchString(st.station_id) === normalizedTarget ||
    st.aliases.some(a => normalizeSearchString(a) === normalizedTarget)
  );
}
